WITH flattened_attrs AS (SELECT id, service, host, log_ts, level, payload_json, context['trace'] AS trace, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region FROM app_logs WHERE TO_DATE(log_ts) >= '2024-05-01') SELECT *, MAX(retry_count) OVER (PARTITION BY host, level) AS host_max_retry_count, SUM(retry_count) OVER (ORDER BY retry_count, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_retry_count FROM flattened_attrs
